<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Comandas automotivas</h1><p class="text-secondary mb-0">Serviços, adicionais, consumo e pagamento por veículo.</p></div><a href="/auto/jobs" class="btn btn-outline-secondary">Ordens</a></div><div class="card"><div class="table-responsive"><table class="table mb-0 align-middle"><thead><tr><th>#</th><th>Cliente</th><th>Veículo</th><th>Total</th><th>Pago</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($commands as $c):?><tr><td>#<?=(int)$c['id']?></td><td><?=htmlspecialchars($c['customer_name'])?></td><td><?=htmlspecialchars(trim(($c['make']??'').' '.$c['model'].' '.($c['plate']??'')))?></td><td>R$ <?=number_format((float)$c['total_amount'],2,',','.')?></td><td>R$ <?=number_format((float)$c['paid_amount'],2,',','.')?></td><td><?=htmlspecialchars($c['status'])?></td><td><a href="/auto/commands/<?=(int)$c['id']?>" class="btn btn-sm btn-outline-primary">Abrir</a></td></tr><?php endforeach;?></tbody></table></div></div>
